export const deadSignal = <T>(
  input: T,
  nonNullableInitialValue?: NonNullable<T extends Record<string, any> ? {} : T>,
): DeadSignal<T> => {
  const baseSignal = getBaseSignal<T>(input);
  const valueDescriptor = Object.getOwnPropertyDescriptor(baseSignal, "value")!;

  Object.defineProperty(baseSignal, "value", {
    configurable: valueDescriptor.configurable,
    enumerable: valueDescriptor.enumerable,
    get: valueDescriptor.get!,
    set() {},
  });

  const deadSignal = Object.assign(baseSignal, {
    type: "dead-signal",
    mutate: undefined,
    dispose() {},
  }) as BaseDeadSignal<T>;

  Object.assign(
    deadSignal,
    getGenericMethods<"non-live", T>(deadSignal as any),
  );
  Object.assign(
    deadSignal,
    getNonMutatingDataMethods<"non-live", T>(
      deadSignal as any,
      nonNullableInitialValue,
    ),
  );
  return deadSignal as any;
};

export const getBaseSignal = <T>(initialValue: T) => {
  let _prevValue: T | undefined = undefined;
  let _value: T = newVal(initialValue);
  const _effects = new Set<Effect>();

  const _catchNewReceiverIfAny = (): void => {
    const newEffect = EffectHook.getCurrentEffect();
    if (newEffect) {
      newEffect.registerStimulusSignal(base);
      _effects.add(newEffect);
    }
  };

  const base = {
    get prevValue(): T | undefined {
      return _prevValue;
    },

    get nonReactiveValue(): T {
      return _value;
    },

    get value(): T {
      _catchNewReceiverIfAny();
      return newVal(_value);
    },

    set value(newValue: T) {
      if (_value === newValue) {
        console.log(`Unnecessary value change - ${newValue}`);
        return;
      }

      _prevValue = _value;
      _value = newValue;
      _effects.forEach((effect) => effect.run());
    },

    mutateWith(mutatedValueEvaluator: (oldValue: T) => T) {
      const updatedValue = mutatedValueEvaluator(_value);
      this.value = updatedValue;
    },

    removeEffect(effect: Effect): void {
      if (!_effects.has(effect))
        throw `Receiver doesn't exist in current signal.`;
      _effects.delete(effect);
    },

    dispose(): void {
      _effects.clear();
    },
  } as const;

  return base;
};

export const dispose = <T extends any[]>(
  ...derivedSignalsOrEffects: { [K in keyof T]: DerivedSignal<T[K]> | Effect }
): void => {
  derivedSignalsOrEffects.forEach((derSigOrEff) => derSigOrEff.dispose());
};

examples:
```typescript
const count = signal(0);
const doubled = derive(() => count.value * 2);
const eff = effect(() => console.log(count.value));

// Dispose single
dispose(doubled);

// Dispose multiple
dispose(doubled, eff);

// Mixed disposal
dispose(doubled, eff);

// Empty (no-op)
dispose();
```

