    orBothEqual: (
      subjectValue: MaybeSignal<any>,
      compareValue: MaybeSignal<any>,
    ) =>
      genericOp(() => {
        const val = evaluator();
        const comparisonResult = value(subjectValue) === value(compareValue);
        return val || comparisonResult;
